<?php declare(strict_types=1); namespace App\Domain\Arena\Service; final class DuelScoring { /** @param list<array{userId:string,correct:bool,receivedAt:\DateTimeImmutable,id:string}> $answers @return array<string,array{points:int,correctRank:?int}> */ public function score(array $answers): array { usort($answers, static fn(array $a,array $b):int => [$a['receivedAt']->format('U.u'),$a['id']] <=> [$b['receivedAt']->format('U.u'),$b['id']]); $rank=0;$result=[];foreach($answers as $answer){if(!$answer['correct']){$result[$answer['userId']]=['points'=>-25,'correctRank'=>null];continue;}$rank++;$result[$answer['userId']]=['points'=>match($rank){1=>100,2=>75,3=>50,default=>25},'correctRank'=>$rank];}return $result;} }
